-- V001: initial server schema for Beetle Keeper.
--
-- Mirrors the on-device SQLite (Drift) model. Every synchronizable table has:
--   id          UUID primary key generated by the client (stable across devices)
--   created_at  / updated_at  timestamptz (UTC)
--   deleted_at  tombstone (rows are never hard-deleted by the app)
--   revision    incremented on every update (optimistic concurrency)
--   change_seq  server-assigned, monotonically increasing; basis for a future
--               incremental pull ("give me everything after change_seq N").
-- Migrations are append-only: never edit an applied file; add V00N instead.

CREATE SEQUENCE IF NOT EXISTS change_seq;

CREATE OR REPLACE FUNCTION touch_row() RETURNS trigger AS $$
BEGIN
  NEW.updated_at := now();
  NEW.revision   := OLD.revision + 1;
  NEW.change_seq := nextval('change_seq');
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE species (
  id                     UUID PRIMARY KEY,
  code                   VARCHAR(8)  NOT NULL UNIQUE CHECK (code ~ '^[A-Z][A-Z0-9]{1,7}$'),
  scientific_name        VARCHAR(120) NOT NULL,
  common_name            TEXT,
  is_builtin             BOOLEAN NOT NULL DEFAULT FALSE,
  expected_pupa_days_min INTEGER CHECK (expected_pupa_days_min > 0),
  expected_pupa_days_max INTEGER CHECK (expected_pupa_days_max > 0),
  notes                  TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq'),
  CHECK (expected_pupa_days_min IS NULL OR expected_pupa_days_max IS NULL
         OR expected_pupa_days_min <= expected_pupa_days_max)
);

CREATE TABLE temperature_sensors (
  id               UUID PRIMARY KEY,
  name             VARCHAR(60) NOT NULL,
  location         TEXT,
  kind             TEXT NOT NULL DEFAULT 'manual' CHECK (kind IN ('manual', 'bluetooth', 'wifi')),
  external_id      TEXT,
  min_threshold_c  DOUBLE PRECISION,
  max_threshold_c  DOUBLE PRECISION,
  target_c         DOUBLE PRECISION,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq'),
  CHECK (min_threshold_c IS NULL OR max_threshold_c IS NULL OR min_threshold_c <= max_threshold_c)
);

CREATE TABLE beetles (
  id                      UUID PRIMARY KEY,
  code                    VARCHAR(16) NOT NULL UNIQUE CHECK (code ~ '^[A-Z][A-Z0-9]{1,7}-[0-9]{3,6}$'),
  species_id              UUID NOT NULL REFERENCES species (id),
  sex                     TEXT NOT NULL DEFAULT 'unknown' CHECK (sex IN ('male', 'female', 'unknown')),
  status                  TEXT NOT NULL DEFAULT 'active'
                          CHECK (status IN ('active', 'deceased', 'transferred', 'archived')),
  acquired_at             TIMESTAMPTZ,
  hatch_date              TIMESTAMPTZ,
  estimated_hatch_date    TIMESTAMPTZ,
  hatch_uncertainty_days  INTEGER CHECK (hatch_uncertainty_days >= 0),
  sensor_id               UUID REFERENCES temperature_sensors (id),
  notes                   TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq')
);
CREATE INDEX idx_beetles_species ON beetles (species_id);
CREATE INDEX idx_beetles_status ON beetles (status) WHERE deleted_at IS NULL;

CREATE TABLE weight_records (
  id            UUID PRIMARY KEY,
  beetle_id     UUID NOT NULL REFERENCES beetles (id),
  measured_at   TIMESTAMPTZ NOT NULL,
  weight_grams  DOUBLE PRECISION NOT NULL CHECK (weight_grams > 0 AND weight_grams < 1000),
  notes         TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq')
);
CREATE INDEX idx_weight_beetle_time ON weight_records (beetle_id, measured_at);

CREATE TABLE observation_records (
  id           UUID PRIMARY KEY,
  beetle_id    UUID NOT NULL REFERENCES beetles (id),
  observed_at  TIMESTAMPTZ NOT NULL,
  category     TEXT NOT NULL DEFAULT 'general',
  description  TEXT NOT NULL CHECK (length(description) BETWEEN 1 AND 4000),
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq')
);
CREATE INDEX idx_observation_beetle_time ON observation_records (beetle_id, observed_at);

CREATE TABLE temperature_records (
  id           UUID PRIMARY KEY,
  sensor_id    UUID NOT NULL REFERENCES temperature_sensors (id),
  recorded_at  TIMESTAMPTZ NOT NULL,
  celsius      DOUBLE PRECISION NOT NULL CHECK (celsius BETWEEN -40 AND 80),
  source       TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'sensor')),
  notes        TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq')
);
CREATE INDEX idx_temperature_sensor_time ON temperature_records (sensor_id, recorded_at);

CREATE TABLE substrate_changes (
  id                   UUID PRIMARY KEY,
  beetle_id            UUID NOT NULL REFERENCES beetles (id),
  changed_at           TIMESTAMPTZ NOT NULL,
  substrate_type       TEXT,
  brand                TEXT,
  batch                TEXT,
  quantity_liters      DOUBLE PRECISION CHECK (quantity_liters > 0),
  beetle_weight_grams  DOUBLE PRECISION CHECK (beetle_weight_grams > 0),
  condition            TEXT,
  next_planned_at      TIMESTAMPTZ,
  notes                TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq')
);
CREATE INDEX idx_substrate_beetle_time ON substrate_changes (beetle_id, changed_at);

CREATE TABLE container_changes (
  id                      UUID PRIMARY KEY,
  beetle_id               UUID NOT NULL REFERENCES beetles (id),
  changed_at              TIMESTAMPTZ NOT NULL,
  previous_volume_liters  DOUBLE PRECISION CHECK (previous_volume_liters > 0),
  new_volume_liters       DOUBLE PRECISION NOT NULL CHECK (new_volume_liters > 0),
  beetle_weight_grams     DOUBLE PRECISION CHECK (beetle_weight_grams > 0),
  condition               TEXT,
  notes                   TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq')
);
CREATE INDEX idx_container_beetle_time ON container_changes (beetle_id, changed_at);

CREATE TABLE life_stage_events (
  id            UUID PRIMARY KEY,
  beetle_id     UUID NOT NULL REFERENCES beetles (id),
  occurred_at   TIMESTAMPTZ NOT NULL,
  stage         TEXT NOT NULL CHECK (stage IN ('l1', 'l2', 'l3', 'prepupa', 'pupa', 'adult')),
  l3_phase      TEXT CHECK (l3_phase IN ('early', 'middle', 'late')),
  is_estimated  BOOLEAN NOT NULL DEFAULT FALSE,
  notes         TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq'),
  CHECK (l3_phase IS NULL OR stage = 'l3')
);
CREATE INDEX idx_lifestage_beetle_time ON life_stage_events (beetle_id, occurred_at);

CREATE TABLE ai_analyses (
  id             UUID PRIMARY KEY,
  beetle_id      UUID REFERENCES beetles (id),
  kind           TEXT NOT NULL CHECK (kind IN ('chat', 'proactive', 'vision')),
  provider       TEXT NOT NULL,
  model          TEXT,
  question       TEXT,
  response       TEXT NOT NULL,
  sections_json  JSONB,
  feedback       TEXT CHECK (feedback IN ('helpful', 'notHelpful')),
  outcome        TEXT NOT NULL DEFAULT 'notApplicable'
                 CHECK (outcome IN ('notApplicable', 'pending', 'correct', 'incorrect')),
  outcome_note   TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq')
);
CREATE INDEX idx_analysis_beetle_time ON ai_analyses (beetle_id, created_at);

CREATE TABLE reminders (
  id               UUID PRIMARY KEY,
  beetle_id        UUID REFERENCES beetles (id),
  sensor_id        UUID REFERENCES temperature_sensors (id),
  event_type       TEXT NOT NULL,
  title            VARCHAR(80) NOT NULL,
  message          VARCHAR(500) NOT NULL DEFAULT '',
  due_at           TIMESTAMPTZ NOT NULL,
  status           TEXT NOT NULL
                   CHECK (status IN ('suggested', 'confirmed', 'scheduled', 'completed', 'cancelled', 'expired')),
  source           TEXT NOT NULL CHECK (source IN ('user', 'rule', 'ai')),
  basis            TEXT CHECK (basis IN ('measured', 'calculated', 'ai_inference')),
  severity         TEXT CHECK (severity IN ('info', 'observation', 'warning', 'alert')),
  confidence       TEXT CHECK (confidence IN ('low', 'medium', 'high')),
  reason           TEXT,
  recommendation   TEXT,
  dedupe_key       TEXT,
  period_start     TIMESTAMPTZ,
  period_end       TIMESTAMPTZ,
  analysis_id      UUID REFERENCES ai_analyses (id),
  completed_at     TIMESTAMPTZ,
  postponed_count  INTEGER NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq')
);
CREATE INDEX idx_reminder_status_due ON reminders (status, due_at);
CREATE INDEX idx_reminder_beetle_event ON reminders (beetle_id, event_type);
-- At most one live reminder per observation period (same beetle + event + anchor).
CREATE UNIQUE INDEX uq_reminder_dedupe ON reminders (dedupe_key) WHERE dedupe_key IS NOT NULL AND deleted_at IS NULL;

CREATE TABLE evidence_references (
  id           UUID PRIMARY KEY,
  analysis_id  UUID REFERENCES ai_analyses (id) ON DELETE CASCADE,
  reminder_id  UUID REFERENCES reminders (id) ON DELETE CASCADE,
  record_type  TEXT NOT NULL,
  record_id    UUID NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  deleted_at  TIMESTAMPTZ,
  revision    INTEGER NOT NULL DEFAULT 1,
  change_seq  BIGINT  NOT NULL DEFAULT nextval('change_seq'),
  CHECK (analysis_id IS NOT NULL OR reminder_id IS NOT NULL)
);
CREATE INDEX idx_evidence_analysis ON evidence_references (analysis_id);
CREATE INDEX idx_evidence_reminder ON evidence_references (reminder_id);

-- Attach the touch trigger and a change_seq index to every synchronizable table.
DO $$
DECLARE t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'species', 'temperature_sensors', 'beetles', 'weight_records', 'observation_records',
    'temperature_records', 'substrate_changes', 'container_changes', 'life_stage_events',
    'ai_analyses', 'reminders', 'evidence_references'
  ] LOOP
    EXECUTE format('CREATE TRIGGER trg_%1$s_touch BEFORE UPDATE ON %1$I FOR EACH ROW EXECUTE FUNCTION touch_row()', t);
    EXECUTE format('CREATE INDEX idx_%1$s_change_seq ON %1$I (change_seq)', t);
  END LOOP;
END $$;

